"""Prepend an auto-generated "generated by" info panel to a CSF body.

``generated_by`` follows the :class:`SyncContext` convention: ``None`` means
use the default notice, an empty/blank string suppresses the panel, and any
other string is a template that may contain ``%{filepath}``, ``%{filename}``,
``%{filedir}`` and ``%{filestem}`` placeholders.
"""

from __future__ import annotations

from pathlib import Path
from typing import Optional

from lxml import etree

from sync_confluence.confluence.storage_format._csf_namespaces import (
    AC,
    ElementType,
    qname,
)

DEFAULT_GENERATED_BY = "This page is auto-generated. Do not edit directly."


def apply_generated_by_template(template: str, relative_path: Path) -> str:
    """Substitute the generated-by banner ``%{...}`` path placeholders in *template*."""
    return (
        template.replace("%{filepath}", relative_path.as_posix())
        .replace("%{filename}", relative_path.name)
        .replace("%{filedir}", relative_path.parent.as_posix())
        .replace("%{filestem}", relative_path.stem)
    )


def build_info_panel(text: str) -> ElementType:
    """Build a Confluence info panel macro (info box) holding *text*."""
    paragraph = etree.Element("p")
    paragraph.text = text
    body = AC("rich-text-body")
    body.append(paragraph)
    macro = AC("structured-macro", {qname("ac", "name"): "info"})
    macro.append(body)
    return macro


def prepend_generated_by_banner(
    root: ElementType, generated_by: Optional[str], relative_path: Optional[Path]
) -> None:
    """Insert the generated-by banner (info panel) as the first child of *root*."""
    if generated_by is not None and not generated_by.strip():
        return
    template = DEFAULT_GENERATED_BY if generated_by is None else generated_by
    text = (
        apply_generated_by_template(template, relative_path)
        if relative_path
        else template
    )
    root.insert(0, build_info_panel(text))
